=== argon2
function argon2(algorithm, parameters, callback) {
  if (typeof callback !== "function") throw new TypeError("crypto.argon2: callback must be a function");
  const args = argon2Parameters(algorithm, parameters, "crypto.argon2");
  __password.argon2(...args,
    (bytes) => callback(null, Buffer.from(bytes)),
    (error) => callback(error));
}
=== argon2Sync
function argon2Sync(algorithm, parameters) {
  return Buffer.from(__password.argon2Sync(...argon2Parameters(algorithm, parameters, "crypto.argon2Sync")));
}
=== createHash
(algorithm) => new Hash(algorithm)
=== createHmac
(algorithm, key) => new Hmac(algorithm, key)
=== Hash
class Hash {
  constructor(algorithm) {
    this._reg = resolveHash(algorithm);
    this._chunks = [];
    this._used = false;
  }
  update(data, encoding) {
    this._chunks.push(toBytes(data, encoding));
    return this;
  }
  _bytes() {
    let total = 0;
    for (const c of this._chunks) total += c.length;
    const all = new Uint8Array(total);
    let off = 0;
    for (const c of this._chunks) { all.set(c, off); off += c.length; }
    return all;
  }
  digest(encoding) {
    if (this._used) throw new Error("Digest already called");
    this._used = true;
    const digest = Buffer.from(this._reg.fn(this._bytes()));
    return encoding && encoding !== "buffer" ? digest.toString(encoding) : digest;
  }
  copy() {
    const h = new Hash("md5");
    h._reg = this._reg;
    h._chunks = this._chunks.slice();
    return h;
  }
}
=== Hmac
class Hmac {
  constructor(algorithm, key) {
    this._reg = resolveHash(algorithm);
    this._key = key instanceof KeyObject ? key._material : toBytes(key);
    this._chunks = [];
    this._used = false;
  }
  update(data, encoding) {
    this._chunks.push(toBytes(data, encoding));
    return this;
  }
  digest(encoding) {
    if (this._used) throw new Error("Digest already called");
    this._used = true;
    let total = 0;
    for (const c of this._chunks) total += c.length;
    const all = new Uint8Array(total);
    let off = 0;
    for (const c of this._chunks) { all.set(c, off); off += c.length; }
    const digest = Buffer.from(hmacRaw(this._reg, this._key, all));
    return encoding && encoding !== "buffer" ? digest.toString(encoding) : digest;
  }
}
