    }

    pub fn new224() -> Self {
        Sha256 { state: IV224, buf: [0; 64], buf_len: 0, total: 0, out_len: 28 }
    }

    pub(crate) fn compress(state: &mut [u32; 8], block: &[u8]) {
        let mut w = [0u32; 64];
        for i in 0..16 {
            w[i] = u32::from_be_bytes([block[i * 4], block[i * 4 + 1], block[i * 4 + 2], block[i * 4 + 3]]);
