#[derive(Clone)]
pub struct Sha512 {
    state: [u64; 8],
    buf: [u8; 128],
    buf_len: usize,
    total: u128,
    out_len: usize,
}

impl Sha512 {
    /// `iv` selects the variant; `out_len` is the (truncated) digest length in bytes.
    pub fn with_iv(iv: [u64; 8], out_len: usize) -> Self {
        Sha512 { state: iv, buf: [0; 128], buf_len: 0, total: 0, out_len }
    }

    pub fn new() -> Self {
        Self::with_iv(IV512, 64)
