use super::hash::{HashAlg, Hmac};
use super::CryptoError;

/// PBKDF2-HMAC. `iterations == 0` behaves like 1 (the original's JS loop runs the first
/// HMAC unconditionally). `key_len == 0` yields an empty vector.
pub fn pbkdf2(alg: HashAlg, password: &[u8], salt: &[u8], iterations: u32, key_len: usize) -> Vec<u8> {
    let h_len = alg.output_len();
    let base = Hmac::new(alg, password);
    let mut out = Vec::with_capacity(key_len);
    let mut block_index: u32 = 1;
    let mut u = [0u8; 64];
    let mut t = [0u8; 64];
    while out.len() < key_len {
        let mut mac = base.clone();
        mac.update(salt);
        mac.update(&block_index.to_be_bytes());
        mac.finalize_into(&mut u);
        t[..h_len].copy_from_slice(&u[..h_len]);
        for _ in 1..iterations {
            let mut mac = base.clone();
            mac.update(&u[..h_len]);
            mac.finalize_into(&mut u);
            for k in 0..h_len {
                t[k] ^= u[k];
            }
        }
        let take = (key_len - out.len()).min(h_len);
        out.extend_from_slice(&t[..take]);
        block_index = block_index.wrapping_add(1);
    }
    out
}

/// HKDF-Extract: `PRK = HMAC(salt, ikm)`. An empty salt is equivalent to `HashLen` zero bytes.
pub fn hkdf_extract(alg: HashAlg, salt: &[u8], ikm: &[u8]) -> Vec<u8> {
    let mut m = Hmac::new(alg, salt);
    m.update(ikm);
    m.finalize()
}

/// HKDF-Expand. Errors (RangeError, no code, message
/// `hkdf: requested key length is too large`) when `key_len > 255 * HashLen`.
pub fn hkdf_expand(alg: HashAlg, prk: &[u8], info: &[u8], key_len: usize) -> Result<Vec<u8>, CryptoError> {
    let h_len = alg.output_len();
    let n = key_len.div_ceil(h_len);
    if n > 255 {
        return Err(CryptoError::range_error("hkdf: requested key length is too large"));
    }
    let base = Hmac::new(alg, prk);
    let mut okm = Vec::with_capacity(n * h_len);
    let mut prev: Vec<u8> = Vec::new();
    for i in 1..=n {
        let mut m = base.clone();
        m.update(&prev);
        m.update(info);
        m.update(&[i as u8]);
        prev = m.finalize();
        okm.extend_from_slice(&prev);
    }
    okm.truncate(key_len);
    Ok(okm)
}

/// HKDF (extract + expand), as `crypto.hkdfSync` computes it. The JS layer returns the
/// result as an `ArrayBuffer`.
pub fn hkdf(alg: HashAlg, ikm: &[u8], salt: &[u8], info: &[u8], key_len: usize) -> Result<Vec<u8>, CryptoError> {
    let h_len = alg.output_len();
    if key_len.div_ceil(h_len) > 255 {
        return Err(CryptoError::range_error("hkdf: requested key length is too large"));
    }
    let prk = hkdf_extract(alg, salt, ikm);
    hkdf_expand(alg, &prk, info, key_len)
}

//! CSPRNG access (`/dev/urandom`), UUIDv4, `randomInt`, `timingSafeEqual`.

use std::fs::File;
use std::io::Read;
use std::sync::Mutex;

const POOL_SIZE: usize = 4096;

struct Pool {
    file: Option<File>,
    buf: Box<[u8; POOL_SIZE]>,
    pos: usize,
}

static POOL: Mutex<Option<Pool>> = Mutex::new(None);

fn read_os(file: &mut Option<File>, out: &mut [u8]) {
    if file.is_none() {
        *file = File::open("/dev/urandom").ok();
    }
    if let Some(f) = file.as_mut() {
        if f.read_exact(out).is_ok() {
            return;
        }
    }
    // Extremely unlikely fallback (no /dev/urandom): mix time, addresses and a counter
    // through SHA-512. Not expected to be reached on Linux/macOS.
    fallback_fill(out);
}

fn fallback_fill(out: &mut [u8]) {
    use super::hash::{HashAlg, Hasher};
    use std::sync::atomic::{AtomicU64, Ordering};
    static CTR: AtomicU64 = AtomicU64::new(0);
    let mut off = 0;
    while off < out.len() {
        let mut h = Hasher::new(HashAlg::Sha512);
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_nanos())
            .unwrap_or(0);
        h.update(&now.to_le_bytes());
        h.update(&CTR.fetch_add(1, Ordering::Relaxed).to_le_bytes());
        let local = 0u8;
        h.update(&(&local as *const u8 as usize).to_le_bytes());
        h.update(&std::process::id().to_le_bytes());
        let d = h.finalize();
        let take = (out.len() - off).min(d.len());
        out[off..off + take].copy_from_slice(&d[..take]);
        off += take;
    }
}

/// Fill `buf` with cryptographically secure random bytes (backs `randomFillSync`,
/// `getRandomValues`, `randomBytes`). Small requests are served from a 4 KiB pool.
pub fn fill_random(buf: &mut [u8]) {
    if buf.is_empty() {
        return;
    }
    let mut guard = match POOL.lock() {
        Ok(g) => g,
        Err(p) => p.into_inner(),
    };
    let pool = guard.get_or_insert_with(|| Pool { file: None, buf: Box::new([0u8; POOL_SIZE]), pos: POOL_SIZE });
    if buf.len() > POOL_SIZE / 2 {
        read_os(&mut pool.file, buf);
        return;
    }
    let mut off = 0;
    while off < buf.len() {
        if pool.pos >= POOL_SIZE {
            let Pool { file, buf: pbuf, pos } = pool;
            read_os(file, &mut pbuf[..]);
            *pos = 0;
        }
        let take = (buf.len() - off).min(POOL_SIZE - pool.pos);
        buf[off..off + take].copy_from_slice(&pool.buf[pool.pos..pool.pos + take]);
        // Never hand out the same pool bytes twice.
        for b in &mut pool.buf[pool.pos..pool.pos + take] {
            *b = 0;
        }
        pool.pos += take;
        off += take;
    }
}

/// `n` random bytes.
pub fn random_bytes(n: usize) -> Vec<u8> {
    let mut v = vec![0u8; n];
    fill_random(&mut v);
    v
}

/// Format 16 bytes as a lower-case 8-4-4-4-12 UUID string.
pub fn format_uuid(b: &[u8; 16]) -> String {
    const HEX: &[u8; 16] = b"0123456789abcdef";
    let mut s = String::with_capacity(36);
    for (i, byte) in b.iter().enumerate() {
        if i == 4 || i == 6 || i == 8 || i == 10 {
            s.push('-');
        }
        s.push(HEX[(byte >> 4) as usize] as char);
        s.push(HEX[(byte & 15) as usize] as char);
    }
    s
}

/// RFC 4122 version-4 UUID, lower-case (`crypto.randomUUID()`).
pub fn random_uuid() -> String {
    let mut b = [0u8; 16];
    fill_random(&mut b);
    b[6] = (b[6] & 0x0f) | 0x40;
    b[8] = (b[8] & 0x3f) | 0x80;
    format_uuid(&b)
}

/// Uniform integer in `[min, max)`, using the original's rejection-sampling algorithm:
/// `range = max - min`, `bytes = max(1, ceil(ceil(log2(range)) / 8))`, draw big-endian
/// `bytes`-byte values `v` until `v < 2^(8*bytes) - (2^(8*bytes) % range)`, return
/// `min + v % range`. Returns `None` when `max <= min` (the JS layer throws
/// RangeError `The value of "max" is out of range. It must be greater than the value of "min".`).
/// Safe-integer validation (`randomInt: min and max must be safe integers`) is the binding's job.
pub fn random_int(min: i64, max: i64) -> Option<i64> {
    if max <= min {
        return None;
    }
    let range = (max as i128 - min as i128) as u128;
    // ceil(log2(range)) — for range == 1 this is 0.
    let bits = if range <= 1 { 0 } else { 128 - (range - 1).leading_zeros() } as usize;
    let bytes = bits.div_ceil(8).max(1);
    let modulus: u128 = 1u128 << (bytes * 8);
    let limit = modulus - (modulus % range);
    loop {
        let mut b = [0u8; 16];
        fill_random(&mut b[..bytes]);
        let mut v: u128 = 0;
        for x in &b[..bytes] {
            v = (v << 8) | *x as u128;
        }
        if v < limit {
            return Some((min as i128 + (v % range) as i128) as i64);
        }
    }
}

/// Constant-time equality. Returns `false` for different lengths (the JS layer throws
/// RangeError `Input buffers must have the same byte length` before calling this).
pub fn timing_safe_eq(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() {
        return false;
    }
    let mut diff = 0u8;
    for (x, y) in a.iter().zip(b.iter()) {
        diff |= x ^ y;
    }
    std::hint::black_box(diff) == 0
}

//! Pure-Rust crypto primitives behind `node:crypto` / WebCrypto (doc to be completed).

#![allow(dead_code)]

mod error;
