fn keystream_xor(&mut self, mut data: &[u8], out: &mut Vec<u8>) {
    // Use up a partially consumed keystream block first.
    while self.ks_pos < 16 && !data.is_empty() {
        out.push(data[0] ^ self.ks[self.ks_pos]);
        self.ks_pos += 1;
        data = &data[1..];
