//!   `asymmetricKeyType` ('rsa'|'ec'|'ed25519'|'x25519'), `asymmetricKeyDetails` (rsa:
//!   `{modulusLength, publicExponent: <BigInt>}`, ec: `{namedCurve: 'prime256v1'}`, ed/x25519:
